const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const start_date = '2024-10-01';
    const end_date = '2024-10-31';

    // Get country boundaries
    const countries = ee.FeatureCollection("FAO/GAUL/2015/level0");
    const australia = countries.filter(ee.Filter.eq('ADM0_NAME', 'Australia')).geometry();
    const indonesia = countries.filter(ee.Filter.eq('ADM0_NAME', 'Indonesia')).geometry();

    // 2. Data Acquisition & Check
    let s5p_co = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_CO')
      .filterDate(start_date, end_date)
      .filterBounds(australia.union(indonesia)) // Filter by combined bounds to be efficient
      .select('CO_column_number_density', 'qa_value');

    const initial_size = await s5p_co.size().getInfo();
    console.log(`Initial image count for Oct 2024: ${initial_size}`);

    if (initial_size === 0) {
      console.log("No data found for the specified date range (October 2024). This is a future date.");
      console.log("C1");
      return;
    }

    // This part would be executed if there were data (e.g., if date was in the past)
    // 3. Processing (if data existed)
    // Filter by qa_value for quality data
    s5p_co = s5p_co.filter(ee.Filter.gt('qa_value', 0.75));

    const qa_filtered_size = await s5p_co.size().getInfo();
    console.log(`QA-filtered image count: ${qa_filtered_size}`);

    if (qa_filtered_size === 0) {
      console.log("No valid images after QA filtering.");
      console.log("C2");
      return;
    }

    // Take the mean image over the period
    const co_mean_image = s5p_co.mean().multiply(1e6); // Convert from mol/m^2 to mol/cm^2 * 1e-2 and then to ppm, roughly 1e6

    // Set scale for reduceRegion (larger scale to prevent memory issues for large polygons)
    const scale = 5000; // meters

    // Calculate mean CO for Australia
    const co_australia_val = await co_mean_image.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: australia,
      scale: scale,
      maxPixels: 1e9,
      crs: 'EPSG:4326', // Explicitly define CRS for consistency
    }).get('CO_column_number_density').getInfo();

    // Calculate mean CO for Indonesia
    const co_indonesia_val = await co_mean_image.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: indonesia,
      scale: scale,
      maxPixels: 1e9,
      crs: 'EPSG:4326',
    }).get('CO_column_number_density').getInfo();

    // Check for C3: Calculation Failure
    if (co_australia_val === null || co_indonesia_val === null || isNaN(co_australia_val) || isNaN(co_indonesia_val)) {
      console.log("Calculation resulted in null or NaN values.");
      console.log("C3");
      return;
    }

    // 5. Validation & Final Answer
    console.log(`Mean CO Australia (mol/m^2 * 1e6): ${co_australia_val ? co_australia_val.toFixed(2) : 'N/A'}`);
    console.log(`Mean CO Indonesia (mol/m^2 * 1e6): ${co_indonesia_val ? co_indonesia_val.toFixed(2) : 'N/A'}`);

    if (co_australia_val > co_indonesia_val) {
      console.log("A"); // Yes
    } else {
      console.log("B"); // No
    }

  } catch (e) {
    console.error("An error occurred during analysis: ", e);
    console.log("D"); // General error
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
